import { useMemo, useState } from 'react';
import { styled, useTheme } from 'styled-components';
import { Button, Dropdown, EntityListModals, EntityListView, HtmlView, Icon, InfoBanner, cardActionIcon } from '@microteia/ui';
import { useEntityList, useCollection, useCurrentUser, useLookup, useOpenRecord, useWorkspace } from '@microteia/data';
import { getConfigColor } from '@microteia/theme';

const SOURCE_ID = 'microteia:push';

const Card = styled.div`
  background: ${({ theme }) => theme.colors.surface};
  border: 1px solid ${({ theme }) => theme.colors.border};
  border-left: 3px solid ${({ $accent }) => $accent};
  border-radius: ${({ theme }) => theme.borderRadius.lg};
  padding: ${({ theme }) => theme.spacing.md};
  display: flex;
  flex-direction: column;
  gap: ${({ theme }) => theme.spacing.sm};
`;

const Head = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: ${({ theme }) => theme.spacing.md};
  flex-wrap: wrap;
`;

const Subject = styled.div`
  font-size: ${({ theme }) => theme.fontSizes.sm};
  font-weight: 600;
  color: ${({ theme }) => theme.colors.text};
`;

const Line = styled.div`
  font-size: ${({ theme }) => theme.fontSizes.xs};
  color: ${({ theme }) => theme.colors.textMuted};
`;

const Meta = styled.div`
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  font-size: ${({ theme }) => theme.fontSizes.xs};
  color: ${({ theme }) => theme.colors.textMuted};
`;

const Chip = styled.span`
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 7px;
  border-radius: ${({ theme }) => theme.borderRadius.full};
  font-size: 10px;
  font-weight: 600;
  background: ${({ $color, theme }) => ($color || theme.colors.textMuted) + '20'};
  color: ${({ $color, theme }) => $color || theme.colors.textMuted};
  border: 1px solid ${({ $color, theme }) => ($color || theme.colors.textMuted) + '40'};
`;

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: ${({ theme }) => theme.spacing.sm};
  padding-top: ${({ theme }) => theme.spacing.sm};
  border-top: 1px solid ${({ theme }) => theme.colors.border};
`;

const Label = styled.div`
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: ${({ theme }) => theme.colors.textMuted};
  margin-bottom: 2px;
`;

const Value = styled.div`
  font-size: ${({ theme }) => theme.fontSizes.xs};
  color: ${({ theme }) => theme.colors.text};
`;

const CaseLink = styled.button`
  font-size: ${({ theme }) => theme.fontSizes.xs};
  font-family: ${({ theme }) => theme.fonts.mono};
  color: ${({ theme }) => theme.colors.primary};
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-align: left;

  &:hover { text-decoration: underline; }
`;

const Foot = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: ${({ theme }) => theme.spacing.sm};
  padding-top: ${({ theme }) => theme.spacing.sm};
  border-top: 1px solid ${({ theme }) => theme.colors.border};
`;

const FootLeft = styled.div`
  display: flex;
  align-items: center;
  gap: ${({ theme }) => theme.spacing.xs};
`;

const ActionsButton = styled.button`
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: ${({ theme }) => theme.borderRadius.md};
  border: 1px solid ${({ theme }) => theme.colors.border};
  background: ${({ theme }) => theme.colors.surface};
  color: ${({ theme }) => theme.colors.textSecondary};
  font-size: ${({ theme }) => theme.fontSizes.xs};
  cursor: pointer;
  transition: ${({ theme }) => theme.transitions.fast};

  &:hover { background: ${({ theme }) => theme.colors.surfaceHover}; color: ${({ theme }) => theme.colors.text}; }
`;

const PlainBody = styled.pre`
  margin: 0;
  padding: ${({ theme }) => theme.spacing.sm};
  max-height: 420px;
  overflow: auto;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: ${({ theme }) => theme.fonts.mono};
  font-size: ${({ theme }) => theme.fontSizes.xs};
  color: ${({ theme }) => theme.colors.textSecondary};
  background: ${({ theme }) => theme.colors.surface};
  border: 1px solid ${({ theme }) => theme.colors.border};
  border-radius: ${({ theme }) => theme.borderRadius.md};
`;

const HeaderCount = styled.span`
  padding: 2px 8px;
  border-radius: ${({ theme }) => theme.borderRadius.full};
  background: ${({ theme }) => theme.colors.warning};
  color: ${({ theme }) => theme.colors.white};
  font-size: 11px;
  font-weight: 700;
`;

const HeaderTools = styled.div`
  display: flex;
  align-items: center;
  gap: ${({ theme }) => theme.spacing.sm};
`;

const dateOf = (value) => {
  if (!value) return null;
  const d = value instanceof Date ? value : new Date(String(value));
  return isNaN(d.getTime()) ? null : d;
};

const stamp = (value) => {
  const d = dateOf(value);
  if (!d) return '';
  return d.toLocaleString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
};

// A caixa se lê do e-mail mais RECENTE ao mais antigo; a ordem por data de gravação não serve, porque
// a ingestão processa em lote e um e-mail de ontem pode ser gravado depois de um de hoje.
const byReceivedAtDesc = (a, b) => {
  const at = dateOf(a.receivedAt) ? dateOf(a.receivedAt).getTime() : 0;
  const bt = dateOf(b.receivedAt) ? dateOf(b.receivedAt).getTime() : 0;
  return bt - at;
};

// A visão útil de quem abre a caixa é o que ainda não foi triado.
const PENDENTES = [{ key: 'status', values: ['pending'] }];

/**
 * De quem o e-mail veio, e se dá para confiar no HTML dele. Domínio do Judiciário e o portal de
 * publicações — o resto é exibido como TEXTO, sem interpretar marcação nenhuma.
 *
 * Vale reparar no que essa decisão NÃO decide mais: mesmo o remetente confiável é exibido dentro de
 * uma moldura isolada, sem script e sem acesso à aplicação. Errar aqui custa uma página feia, e não
 * a sessão de quem está lendo.
 */
const senderAddress = (from) => {
  const raw = String(from || '');
  const angle = raw.match(/<([^>]+)>/);
  if (angle) return angle[1].toLowerCase();
  const plain = raw.match(/[^\s<>]+@[^\s<>]+/);
  return plain ? plain[0].toLowerCase() : raw.toLowerCase();
};

const isTrustedSender = (from) => {
  const address = senderAddress(from);
  return address.endsWith('.jus.br') || address.endsWith('@publicacoesonline.com.br');
};

const asPlainText = (record) =>
  record.emailBodyText || String(record.emailBodyHtml || '').replace(/<[^>]*>/g, '');

export default function PushesView() {
  const theme = useTheme();
  const list = useEntityList(SOURCE_ID, { defaultFilterTokens: PENDENTES, sortRecords: byReceivedAtDesc });
  const cases = useCollection('cases');
  const statusOptions = useLookup('pushStatuses');
  const openRecord = useOpenRecord();
  const viewer = useCurrentUser();
  const { openTab } = useWorkspace();
  const [expanded, setExpanded] = useState({});

  const caseIdByNumber = useMemo(() => {
    const index = {};
    for (const item of cases) if (item.caseNumber) index[item.caseNumber] = item.id;
    return index;
  }, [cases]);

  const pendingCount = useMemo(
    () => list.records.filter((record) => record.status === 'pending').length,
    [list.records],
  );

  if (!list.definition) {
    return <div style={{ padding: '24px' }}><InfoBanner message='Tela "Pushes do Tribunal" não encontrada. Instale a extensão para ativá-la.' variant="warning" /></div>;
  }

  const statusLabel = (record) => {
    const option = statusOptions.find((item) => item.key === record.status);
    return option ? option.label : record.status || 'Sem situação';
  };

  const toggleBody = (id) => setExpanded((prev) => ({ ...prev, [id]: !prev[id] }));

  const renderProcess = (record) => {
    const caseId = caseIdByNumber[record.processNumber];
    if (caseId) {
      return (
        <CaseLink title={'Abrir processo ' + record.processNumber} onClick={() => openRecord('cases', caseId)}>
          {record.processNumber}
        </CaseLink>
      );
    }
    return (
      <div>
        <Value>{record.processNumber}</Value>
        <Chip $color={theme.colors.warning}><Icon name="alert" size={10} />Processo não cadastrado</Chip>
      </div>
    );
  };

  const renderInfo = (label, value) => (value ? (
    <div><Label>{label}</Label><Value>{value}</Value></div>
  ) : null);

  const renderCard = (record) => {
    const trusted = isTrustedSender(record.from);
    const isOpen = !!expanded[record.id];
    const actions = list.getCardActions(record);
    return (
      <Card key={record.id} $accent={getConfigColor(statusOptions, record.status, theme)}>
        <Head>
          <div>
            <Subject>{record.subject || '(sem assunto)'}</Subject>
            <Line>De: {record.from}</Line>
            <Line>Para: {record.to}</Line>
          </div>
          <Meta>
            <Chip $color={getConfigColor(statusOptions, record.status, theme)}>{statusLabel(record)}</Chip>
            <Chip>{record.parsedByAI ? 'IA' : 'Regex'}</Chip>
            <span>{stamp(record.receivedAt)}</span>
          </Meta>
        </Head>

        {record.processNumber ? (
          <Grid>
            <div><Label>Processo</Label>{renderProcess(record)}</div>
            {renderInfo('Tribunal', record.court)}
            {renderInfo('Polo ativo', record.activeParty)}
            {renderInfo('Polo passivo', record.passiveParty)}
            {renderInfo('Classe judicial', record.legalClass)}
            {renderInfo('Autuação', dateOf(record.filingDate) ? dateOf(record.filingDate).toLocaleDateString('pt-BR') : '')}
          </Grid>
        ) : null}

        {record.parsingError ? (
          <InfoBanner message={'Erro de processamento: ' + record.parsingError} variant="warning" />
        ) : null}

        <Foot>
          <FootLeft>
            <Button size="sm" variant="ghost" onClick={() => toggleBody(record.id)}>
              <Icon name={isOpen ? 'eyeOff' : 'eye'} size={14} />
              {isOpen ? 'Ocultar e-mail' : 'Ver e-mail completo'}
            </Button>
            {trusted ? <Chip $color={theme.colors.success}><Icon name="shieldCheck" size={10} />Fonte confiável</Chip> : null}
          </FootLeft>
          {actions.length > 0 ? (
            <Dropdown
              align="right"
              trigger={<ActionsButton><Icon name="more" size={14} /><span>Ações</span></ActionsButton>}
              items={actions.map((action) => ({
                id: action.key,
                label: action.title,
                icon: cardActionIcon(action),
                variant: action.danger ? 'danger' : 'default',
                onClick: action.onClick,
              }))}
            />
          ) : null}
        </Foot>

        {isOpen ? (
          trusted && record.emailBodyHtml
            ? <HtmlView html={record.emailBodyHtml} />
            : <PlainBody>{asPlainText(record).trim() || 'Sem conteúdo disponível.'}</PlainBody>
        ) : null}
      </Card>
    );
  };

  return (
    <EntityListView
      title={list.definition.titlePlural}
      titleIcon={<Icon name="inbox" size={22} />}
      layout="list"
      onNew={() => {}}
      newTitle=""
      canCreate={false}
      headerExtra={(
        <HeaderTools>
          {pendingCount > 0 ? <HeaderCount>{pendingCount}</HeaderCount> : null}
          {viewer.tenantRole === 'admin' ? (
            <Button size="sm" variant="ghost" title="Configurar recebimento" onClick={() => openTab('push-settings')}>
              <Icon name="settings" size={16} />
              Recebimento
            </Button>
          ) : null}
        </HeaderTools>
      )}
      filterDefs={list.filterDefs}
      filterTokens={list.filterTokens}
      onFilterChange={list.setFilterTokens}
      filterPlaceholder="Filtrar pushes..."
      savedFiltersScreenKey={list.savedFiltersScreenKey}
      isLoading={list.isLoading && list.records.length === 0}
      isEmpty={list.filteredRecords.length === 0}
      emptyIcon={<Icon name="inbox" size={32} />}
      emptyTitle="Nenhum push encontrado"
      emptyActionLabel=""
      modals={<EntityListModals vm={list} />}
    >
      {list.filteredRecords.map(renderCard)}
    </EntityListView>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { styled, useTheme } from 'styled-components';
import { Button, ConfirmModal, Icon, InfoBanner, Spinner } from '@microteia/ui';
import { useCurrentUser, useNotify, useWorkspace } from '@microteia/data';
import { useSettingValue } from '@microteia/settings';
import { useCallable } from '@microteia/functions';

const GSI_SRC = 'https://accounts.google.com/gsi/client';

const Page = styled.div`
  padding: ${({ theme }) => theme.spacing.xl};
  height: 100%;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: ${({ theme }) => theme.spacing.xl};
`;

const Header = styled.div`
  display: flex;
  align-items: center;
  gap: ${({ theme }) => theme.spacing.sm};
`;

const Title = styled.h1`
  margin: 0;
  font-size: ${({ theme }) => theme.fontSizes.xl};
  color: ${({ theme }) => theme.colors.text};
`;

const Section = styled.section`
  display: flex;
  flex-direction: column;
  gap: ${({ theme }) => theme.spacing.sm};
`;

const SectionTitle = styled.h2`
  margin: 0;
  font-size: ${({ theme }) => theme.fontSizes.md};
  color: ${({ theme }) => theme.colors.text};
`;

const SectionText = styled.p`
  margin: 0;
  font-size: ${({ theme }) => theme.fontSizes.sm};
  color: ${({ theme }) => theme.colors.textSecondary};
`;

const Card = styled.div`
  display: flex;
  align-items: center;
  gap: ${({ theme }) => theme.spacing.md};
  background: ${({ theme }) => theme.colors.surface};
  border: 1px solid ${({ theme }) => theme.colors.border};
  border-radius: ${({ theme }) => theme.borderRadius.lg};
  padding: ${({ theme }) => theme.spacing.md};
`;

const CardBody = styled.div`
  flex: 1;
  min-width: 0;
`;

const CardName = styled.div`
  font-size: ${({ theme }) => theme.fontSizes.sm};
  font-weight: 600;
  color: ${({ theme }) => theme.colors.text};
`;

const CardMeta = styled.div`
  font-size: ${({ theme }) => theme.fontSizes.xs};
  color: ${({ theme }) => theme.colors.textMuted};
`;

const IconWrapper = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: ${({ theme }) => theme.borderRadius.md};
  color: ${({ $color }) => $color};
  background: ${({ $color }) => $color + '1a'};
`;

const Empty = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: ${({ theme }) => theme.spacing.sm};
  padding: ${({ theme }) => theme.spacing.xl};
  border: 1px dashed ${({ theme }) => theme.colors.border};
  border-radius: ${({ theme }) => theme.borderRadius.lg};
  color: ${({ theme }) => theme.colors.textMuted};
  font-size: ${({ theme }) => theme.fontSizes.sm};
`;

const Chips = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
`;

const Chip = styled.span`
  padding: 2px 10px;
  border-radius: ${({ theme }) => theme.borderRadius.full};
  border: 1px solid ${({ theme }) => theme.colors.border};
  background: ${({ theme }) => theme.colors.surface};
  font-size: ${({ theme }) => theme.fontSizes.xs};
  color: ${({ theme }) => theme.colors.textSecondary};
`;

const Row = styled.div`
  display: flex;
  align-items: center;
  gap: ${({ theme }) => theme.spacing.sm};
  flex-wrap: wrap;
`;

const List = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${({ theme }) => theme.spacing.sm};
`;

/**
 * O serviço de identidade do Google entra sob DEMANDA, e só aqui: quem nunca abre esta tela não
 * baixa script de terceiro nenhum — o que antes acontecia para todo mundo, no HTML da aplicação.
 */
const loadGoogleIdentity = () => new Promise((resolve, reject) => {
  const ready = () => (window.google && window.google.accounts ? window.google : null);
  const found = ready();
  if (found) return resolve(found);

  const fail = () => reject(new Error('Não foi possível carregar o serviço de identidade do Google.'));
  const done = () => { const google = ready(); return google ? resolve(google) : fail(); };

  const existing = document.querySelector('script[src="' + GSI_SRC + '"]');
  if (existing) {
    existing.addEventListener('load', done);
    existing.addEventListener('error', fail);
    return;
  }

  const script = document.createElement('script');
  script.src = GSI_SRC;
  script.async = true;
  script.defer = true;
  script.addEventListener('load', done);
  script.addEventListener('error', fail);
  document.head.appendChild(script);
});

const stamp = (value) => {
  const date = new Date(String(value));
  return isNaN(date.getTime())
    ? ''
    : date.toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
};

const asList = (value) => (Array.isArray(value) ? value.filter((item) => typeof item === 'string') : []);

export default function PushSettingsView() {
  const theme = useTheme();
  const viewer = useCurrentUser();
  const notify = useNotify();
  const { openTab } = useWorkspace();
  const listConnections = useCallable('listGmailConnections');
  const exchangeCode = useCallable('exchangeGmailCode');
  const revokeConnection = useCallable('revokeGmailConnection');

  const senders = asList(useSettingValue('push.allowedSenders'));
  const subjects = asList(useSettingValue('push.allowedSubjects'));

  const [setup, setSetup] = useState({ connections: [], clientId: '', scope: '' });
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthorizing, setIsAuthorizing] = useState(false);
  const [error, setError] = useState(null);
  const [confirm, setConfirm] = useState({ open: false, id: '', email: '' });

  const isAdmin = viewer.tenantRole === 'admin';

  const load = useCallback(async () => {
    // Quem não é admin não pergunta ao servidor — e não fica esperando: a callable recusaria, e o
    // giro do carregando ficaria para sempre na tela de quem só passou por aqui.
    if (!isAdmin || !viewer.tenantId) {
      setIsLoading(false);
      return;
    }
    try {
      const data = await listConnections({ tenantId: viewer.tenantId });
      setSetup({ connections: data.connections || [], clientId: data.clientId || '', scope: data.scope || '' });
      setError(null);
    } catch (err) {
      setError(err && err.message ? err.message : 'Erro ao carregar as contas autorizadas.');
    } finally {
      setIsLoading(false);
    }
  }, [isAdmin, viewer.tenantId, listConnections]);

  useEffect(() => { void load(); }, [load]);

  const authorize = useCallback(async () => {
    setIsAuthorizing(true);
    try {
      const google = await loadGoogleIdentity();
      if (!setup.clientId) throw new Error('O escritório não tem credencial do Google configurada no servidor.');

      const client = google.accounts.oauth2.initCodeClient({
        client_id: setup.clientId,
        scope: setup.scope,
        ux_mode: 'popup',
        callback: async (response) => {
          if (response.error) {
            notify('Erro na autorização: ' + response.error, 'error');
            setIsAuthorizing(false);
            return;
          }
          if (!response.code) {
            notify('Código de autorização não recebido.', 'error');
            setIsAuthorizing(false);
            return;
          }
          try {
            const connection = await exchangeCode({ code: response.code, tenantId: viewer.tenantId });
            await load();
            notify('Conta ' + connection.email + ' autorizada.', 'success');
          } catch (err) {
            notify(err && err.message ? err.message : 'Erro ao concluir a autorização.', 'error');
          } finally {
            setIsAuthorizing(false);
          }
        },
      });

      client.requestCode();
    } catch (err) {
      notify(err && err.message ? err.message : 'Erro ao iniciar a autorização.', 'error');
      setIsAuthorizing(false);
    }
  }, [setup.clientId, setup.scope, viewer.tenantId, exchangeCode, load, notify]);

  const runRevoke = useCallback(async () => {
    const { id } = confirm;
    setConfirm({ open: false, id: '', email: '' });
    try {
      await revokeConnection({ tenantId: viewer.tenantId, connectionId: id });
      await load();
      notify('Autorização removida.', 'success');
    } catch (err) {
      notify(err && err.message ? err.message : 'Erro ao remover a autorização.', 'error');
    }
  }, [confirm, viewer.tenantId, revokeConnection, load, notify]);

  const renderFilter = (title, items, empty) => (
    <Section>
      <SectionTitle>{title}</SectionTitle>
      {items.length > 0 ? <Chips>{items.map((item) => <Chip key={item}>{item}</Chip>)}</Chips> : <SectionText>{empty}</SectionText>}
    </Section>
  );

  return (
    <Page>
      <Header>
        <Icon name="mailOpen" size={22} />
        <Title>Recebimento de Pushes</Title>
      </Header>

      {!isAdmin ? (
        <InfoBanner message="Só o administrador do escritório configura o recebimento de intimações." variant="info" />
      ) : null}

      <Section>
        <SectionTitle>Contas de e-mail monitoradas</SectionTitle>
        <SectionText>
          As intimações são lidas destas contas. Autorizar é um acordo entre você e o Google: o
          escritório recebe permissão de LEITURA da caixa, e as credenciais ficam no servidor.
        </SectionText>

        {isLoading ? <Spinner /> : (
          <>
            {error ? <InfoBanner message={error} variant="warning" /> : null}

            {setup.connections.length === 0 ? (
              <Empty>
                <Icon name="mail" size={28} />
                <span>Nenhuma conta autorizada neste escritório.</span>
              </Empty>
            ) : (
              <List>
                {setup.connections.map((connection) => (
                  <Card key={connection.id}>
                    <IconWrapper $color={theme.colors.primary}><Icon name="mail" size={18} /></IconWrapper>
                    <CardBody>
                      <CardName>{connection.email}</CardName>
                      <CardMeta>
                        Autorizado por {connection.authorizedByName || 'alguém do escritório'} em {stamp(connection.authorizedAt)}
                      </CardMeta>
                    </CardBody>
                    <Row>
                      <Button size="sm" variant="ghost" title="Reautorizar" disabled={!isAdmin || isAuthorizing} onClick={() => void authorize()}>
                        <Icon name="mailCheck" size={16} />
                      </Button>
                      <Button size="sm" variant="ghost" title="Revogar acesso" disabled={!isAdmin} onClick={() => setConfirm({ open: true, id: connection.id, email: connection.email })}>
                        <Icon name="linkUnlink" size={16} />
                      </Button>
                    </Row>
                  </Card>
                ))}
              </List>
            )}

            <Row>
              <Button disabled={!isAdmin || isAuthorizing} onClick={() => void authorize()}>
                <Icon name="mailAdd" size={16} />
                {isAuthorizing ? 'Autorizando...' : 'Autorizar conta Gmail'}
              </Button>
            </Row>
          </>
        )}
      </Section>

      {renderFilter(
        'Remetentes permitidos',
        senders,
        'Nenhum remetente informado: valem os e-mails do Judiciário (.jus.br) e os portais de publicação.',
      )}

      {renderFilter(
        'Assuntos permitidos',
        subjects,
        'Nenhum assunto informado: todo e-mail dos remetentes permitidos é processado.',
      )}

      <Row>
        <SectionText>As duas listas são editadas em Configurações → Pushes do Tribunal.</SectionText>
        <Button size="sm" variant="ghost" onClick={() => openTab('settings')}>
          <Icon name="settings" size={16} />
          Abrir Configurações
        </Button>
      </Row>

      <ConfirmModal
        isOpen={confirm.open}
        title="Remover autorização"
        message={'Deseja remover a autorização da conta "' + confirm.email + '"? As intimações já recebidas continuam no escritório.'}
        confirmLabel="Remover"
        variant="danger"
        onConfirm={() => void runRevoke()}
        onCancel={() => setConfirm({ open: false, id: '', email: '' })}
      />
    </Page>
  );
}
